// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

const URL_RE = /^(https?):\/\/(?:[^/?#@]*@)?([^/?#:\s]+)(?::(\d{1,5}))?([^?#]*)(\?[^#]*)?(#.*)?$/i;

// Minimal URL parser (n8n's Code sandbox has no URL class). Returns null for anything that is not http(s).
function parseUrl(value) {
  const m = str(value).match(URL_RE);
  if (!m) return null;
  const hostname = m[2].toLowerCase().replace(/\.$/, '');
  if (!hostname.includes('.') || hostname.startsWith('.') || hostname.includes('..')) return null;
  return {
    protocol: m[1].toLowerCase() + ':',
    hostname,
    port: m[3] || '',
    pathname: m[4] ? (m[4].startsWith('/') ? m[4] : '/' + m[4]) : '/',
    search: m[5] && m[5] !== '?' ? m[5] : '',
    hash: m[6] || '',
  };
}

function hostOf(url) {
  const u = parseUrl(url);
  return u ? u.hostname.replace(/^www\./, '') : '';
}

function truncate(s, max) {
  const t = str(s);
  return t.length <= max ? t : t.slice(0, Math.max(0, max - 1)).trimEnd() + '…';
}

// Turns "Sunrise Family Dental & Orthodontics, LLC" into "Sunrise Family Dental" for friendlier copy.
function shortBusinessName(name) {
  let s = str(name)
    .replace(/\s*[,|–—-]\s*(llc|inc|ltd|pllc|pc|co|corp|pvt\.? ltd|private limited)\.?$/i, '')
    .replace(/\s*\((.*?)\)\s*$/, '');
  const cut = s.split(/\s+[|–—]\s+|\s+-\s+/)[0];
  s = cut && cut.length >= 3 ? cut : s;
  return s.trim() || str(name);
}

// ---- places.js ----

// HTTP status from a Google error body ({code: 403}) or an n8n error item ({status: 403, statusCode: 403, httpCode: '403'}).
function httpStatusOf(err) {
  const e = err || {};
  for (const v of [e.httpCode, e.statusCode, e.status, e.code, e.response && e.response.status]) {
    const n = int(v, 0);
    if (n >= 100 && n < 600 && /^\d+$/.test(String(v).trim())) return n;
  }
  const m = str(e.message).match(/^(\d{3})\b/);
  return m ? Number(m[1]) : 0;
}

// Collects every string inside an error payload. n8n stores API errors in different shapes
// ({message: '403 - "{...}"'}, {error: '{"error":{...}}', statusCode}, {description}), so checks run on all of it.
function errorText(err) {
  const parts = [];
  const walk = (v, depth) => {
    if (v === null || v === undefined || depth > 4) return;
    if (typeof v === 'string') {
      parts.push(v.replace(/\\"/g, '"'));
      return;
    }
    if (typeof v !== 'object') return;
    for (const k of ['message', 'description', 'error', 'status', 'statusText', 'body', 'details']) if (k in v) walk(v[k], depth + 1);
  };
  walk(err, 0);
  return parts.join(' | ');
}

// The most useful single message inside an error payload (the API's own message when present).
function errorSummary(err) {
  const text = errorText(err);
  const m = text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) return m[1];
  const e = err || {};
  return str(typeof e === 'string' ? e : e.message || e.description || text).slice(0, 300);
}

